-- BACKUP: bak_20261028_cluster_e_c2_issues
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261028_cluster_e_c2_issues b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261028_cluster_e_c2_issues); UPDATE portfolio_gaps SET status = 'open', resolved_at = NULL WHERE entity IN ('qnfo-cf-one-dashboard', 'W.qnfo-cf-one-dashboard') AND detail LIKE '%cluster-e-c%'; DELETE FROM issue_project_map WHERE issue_id = 1000598 AND project_code = 'YT.SHORTS'; UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261028_cluster_e_c2_contract b WHERE b.class = 'issue-1000315'), verify_transport = 'external-https' WHERE class = 'issue-1000315';

CREATE TABLE IF NOT EXISTS bak_20261028_cluster_e_c2_issues AS SELECT id, description FROM agent_issues WHERE id IN (2993, 99953, 1000315, 1000319, 1000582, 1000583, 1000591, 1000598, 1000703, 1000704);
CREATE TABLE IF NOT EXISTS bak_20261028_cluster_e_c2_contract AS SELECT class, verify_probe, verify_transport FROM remediation_contracts WHERE class = 'issue-1000315';

UPDATE portfolio_gaps SET status = 'resolved', resolved_at = datetime('now'),
  detail = COALESCE(detail, '') || ' | resolved 2026-10-28 cluster-e-c: deployment_history 2662 (deployed, success, 2026-10-28T14:21:01Z) records the live deployment'
WHERE status = 'open' AND kind IN ('deploy-unrecorded', 'project-stale-deploy') AND entity IN ('qnfo-cf-one-dashboard', 'W.qnfo-cf-one-dashboard')
  AND EXISTS (SELECT 1 FROM deployment_history d WHERE d.resource_name = 'qnfo-cf-one-dashboard' AND d.action IN ('deploy', 'deployed') AND COALESCE(d.status, 'success') = 'success');

INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at)
SELECT 1000598, 'YT.SHORTS', 'QNFO.REACH', 'fix', datetime('now')
WHERE EXISTS (SELECT 1 FROM projects WHERE project_code = 'YT.SHORTS');

UPDATE remediation_contracts SET
  verify_probe = 'SELECT ''archived'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM portfolio_actions WHERE action = ''archive'' AND status = ''committed'' AND repo LIKE ''%qnfo-ensemble-research'') AND (SELECT COUNT(*) FROM research_run_ledger WHERE status = ''ok'' AND repo = ''QNFO/qnfo-research'') >= 3 THEN ''archived'' ELSE ''pending: no committed archive row or fewer than 3 consolidated deposits'' END AS observed',
  verify_transport = 'd1-query', last_verdict = 're-armed:cluster-e-c', next_due_at = datetime('now'), attempts = 0
WHERE class = 'issue-1000315' AND verify_transport = 'external-https';

UPDATE agent_issues SET description = description || char(10) || char(10) || 'CLUSTER-E-C 2026-10-28 (live reads): QNFO/qnfo-ensemble-research IS archived (GitHub API archived true, updated_at 2026-10-27T05:01:08Z; portfolio_actions 2585 archive-request and 2587 archive, committed 2026-10-27; research_run_ledger holds 9 ok rows, provenance/IMPORT.json and 406 runs/ entries exist in QNFO/qnfo-research). The runtime probe read absent because it is an anonymous api.github.com read from a Worker (rate-limited address); the contract now reads the fleet own ledger (class issue-1000315, d1-query) and closes the issue on its next pass.'
WHERE id = 1000315 AND status = 'open' AND description NOT LIKE '%CLUSTER-E-C 2026-10-28%';

